<?php
require_once __DIR__.'/outflow_global_rule.php';
// Allocate only this incoming batch; never rebalance existing platform balances.
function incoming_rows($b){
 if(!$b||$b['status']!=='To Review')throw new Exception('This inflow is not pending review.');inflow_duplicate_review($b);
 $r=json_decode($b['result_json']??'[]',true)?:[];$raw=[];
 if($b['batch_type']==='Receipt PDF'){$q=db()->prepare('SELECT * FROM receipt_staging_lines WHERE batch_id=? ORDER BY line_no');$q->execute([$b['id']]);foreach($q as $x){if($x['validation_status']!=='Matched')throw new Exception('Validate every receipt line first.');$x['qty']=$x['final_qty'];$raw[]=$x;}}
 elseif($b['batch_type']==='Excel Upload'){if($b['error_count'])throw new Exception('Resolve upload errors before allocation.');$raw=$r['bulk_rows']??[];}
 elseif($b['batch_type']==='Manual')$raw=[$r];else throw new Exception('Unsupported inflow type.');
 if(!$raw)throw new Exception('No incoming products.');$rows=[];
 foreach($raw as $x){$p=active_product($x['product_id']);[$factor,$qty]=receipt_quantity($x['source_qty'],$x['source_uom']);if($factor!==(int)$x['conversion_factor']||$qty!==(int)$x['qty'])throw new Exception('Incoming quantity changed. Review the items again.');$id=(int)$p['id'];if(!isset($rows[$id]))$rows[$id]=['id'=>$id,'name'=>$p['name'],'sku'=>$p['master_sku'],'qty'=>0,'damaged'=>in_array($r['condition']??'',['Damaged / Leak','For Repackaging'],true)];$rows[$id]['qty']+=$qty;if($rows[$id]['qty']>100000000)throw new Exception('Incoming quantity is outside the supported range.');}
 return $rows;
}
function incoming_signature($b,$rows){$data=[];foreach($rows as $x)$data[]=[$x['id'],$x['name'],$x['sku'],$x['qty'],$x['damaged']];$r=json_decode($b['result_json']??'[]',true)?:[];$receipt=null;if($b['batch_type']==='Receipt PDF'){$q=db()->prepare('SELECT product_id,source_qty,source_uom,conversion_factor,final_qty,validation_status FROM receipt_staging_lines WHERE batch_id=? ORDER BY line_no');$q->execute([$b['id']]);$receipt=$q->fetchAll();}return hash('sha256',json_encode([$b['id'],$b['batch_type'],$b['reference_no'],$b['txn_date'],$data,$r['bulk_rows']??null,$r['condition']??null,$r['remarks']??null,$receipt]));}
function incoming_permission($b){return can_action($b['batch_type']==='Receipt PDF'?'confirm_receipt':($b['batch_type']==='Manual'?'add_inflow':'confirm_bulk_inflow'));}
function incoming_plan($rows,$input,$requireFull=true){if(!is_array($input))throw new Exception('Invalid allocation form.');$plan=[];foreach($rows as $id=>$x){$v=$input[$id]??[];if(!is_array($v))throw new Exception('Invalid product allocation.');$sum=0;$line=['product'=>$x['name'],'incoming'=>$x['qty'],'damaged'=>$x['damaged']];foreach(['Shopee','Lazada','TikTok'] as $p){$n=whole_number($v[$p]??'0',$p.' quantity');if($x['damaged']&&$n)throw new Exception('Damaged / Leak cannot be allocated to platforms.');$line[$p]=$n;$sum+=$n;}if($sum>$x['qty'])throw new Exception($x['name'].': platform quantities exceed incoming quantity.');if($requireFull&&!$x['damaged']&&$sum!==$x['qty'])throw new Exception($x['name'].': allocate the full incoming quantity to Shopee, Lazada and TikTok before submitting.');$line['Warehouse']=$x['damaged']?0:$x['qty']-$sum;$line['Non-Sellable']=$x['damaged']?$x['qty']:0;$plan[$id]=$line;}foreach(array_keys($input) as $id)if(!isset($rows[$id]))throw new Exception('Allocation contains a product outside this inflow.');return $plan;}
function save_incoming_allocation($bid,$input,$signature,$revision,$uid){$revision=whole_number($revision,'Review version');if(!is_string($signature))throw new Exception('Invalid review signature.');$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();if(!$b||!incoming_permission($b))throw new Exception('You cannot allocate this inflow.');$rows=incoming_rows($b);$r=json_decode($b['result_json']??'[]',true)?:[];if(!hash_equals(incoming_signature($b,$rows),$signature)||$revision!==(int)($r['incoming_allocation']['revision']??0))throw new Exception('This review changed. Reopen allocation and review the latest quantities.');$r['incoming_allocation']=['signature'=>$signature,'revision'=>$revision+1,'lines'=>incoming_plan($rows,$input),'saved_by'=>$uid,'saved_name'=>current_user()['name'],'saved_at'=>date('Y-m-d H:i:s')];$pdo->prepare('UPDATE inflow_batches SET result_json=? WHERE id=?')->execute([json_encode($r),$bid]);audit('Review inflow allocation','Inflow Batch',$b['batch_ref'],'Allocation saved for final confirmation; no inventory added.');$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function checked_incoming_allocation($b){$rows=incoming_rows($b);$r=json_decode($b['result_json']??'[]',true)?:[];$a=$r['incoming_allocation']??null;if(!$a||!hash_equals(incoming_signature($b,$rows),$a['signature']))throw new Exception('Review and submit the platform allocation before final confirmation.');$plan=incoming_plan($rows,$a['lines']);foreach($rows as $pid=>$row)if(!$row['damaged'])check_platform_alignment($pid);if($plan!==$a['lines'])throw new Exception('Allocation validation changed. Review it again.');if(!hash_equals((string)$a['revision'],(string)($_POST['allocation_revision']??'')))throw new Exception('This final confirmation expired. Reopen the latest allocation.');return $a;}
function post_incoming_allocation($b,$a,$uid){foreach($a['lines'] as $pid=>$x)foreach(['Shopee','Lazada','TikTok'] as $p)if($x[$p])change_platform_stock($p,(int)$pid,$x[$p],$b['reference_no'],$b['txn_date']);$r=json_decode($b['result_json']??'[]',true)?:[];$a['confirmed_by']=$uid;$a['confirmed_at']=date('Y-m-d H:i:s');$r['incoming_allocation']=$a;$r['destination']=array_sum(array_map(fn($x)=>$x['Shopee']+$x['Lazada']+$x['TikTok'],$a['lines']))?'Platform Allocation':'Non-Sellable';foreach($a['lines'] as $pid=>$x)if(!$x['damaged'])check_platform_alignment($pid);db()->prepare('UPDATE inflow_batches SET result_json=? WHERE id=?')->execute([json_encode($r),$b['id']]);return $r;}
function confirm_manual_inflow($bid,$uid){$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT * FROM inflow_batches WHERE id=? FOR UPDATE');$q->execute([$bid]);$b=$q->fetch();if(!$b||$b['batch_type']!=='Manual')throw new Exception('Manual inflow not found.');$a=checked_incoming_allocation($b);$r=json_decode($b['result_json'],true);$pid=$r['product_id'];$qty=$r['qty'];$platform=$r['return_platform'];if($r['condition']==='Good Item'){$pdo->prepare('INSERT INTO inflows(batch_id,txn_date,reference_no,source_name,source_platform,product_id,source_qty,source_uom,conversion_factor,qty,type,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$bid,$b['txn_date'],$b['reference_no'],$r['reference_kind'],'',$pid,$r['source_qty'],$r['source_uom'],$r['conversion_factor'],$qty,$r['reference_kind']==='Return Order'?'Customer Return - Good':'Return From Borrowed',$r['remarks'],$uid]);}else{$pdo->prepare('INSERT INTO non_sellable(txn_date,platform,order_id,product_id,qty,condition_type,action_type,status,origin,sellable_deducted,remarks,user_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$b['txn_date'],$platform==='Warehouse'?'':$platform,$b['reference_no'],$pid,$qty,$r['condition']==='For Repackaging'?'For Repackaging':'Damaged / Leak','For Review',$r['condition']==='For Repackaging'?'Pending':'For Review',$r['reference_kind']==='Return Order'?'Customer Return':'Borrowed Return',0,$r['remarks'],$uid]);$r['non_sellable_id']=(int)$pdo->lastInsertId();if($r['condition']==='For Repackaging')packaging_initialize($r['non_sellable_id']);$b['result_json']=json_encode($r);}$r=post_incoming_allocation($b,$a,$uid);$pdo->prepare("UPDATE inflow_batches SET status='Confirmed',total_qty=?,result_json=? WHERE id=?")->execute([$qty,json_encode($r),$bid]);audit('Confirm manual inflow','Inflow Batch',$b['batch_ref'],$r['condition'].' +'.$qty.' pcs; reviewed allocation posted.');$pdo->commit();return $qty;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
function incoming_table($rows,$plan,$editing){echo '<div class="ia-table-wrap"><table class="ia-table"><thead><tr><th>Product</th><th>Incoming Qty</th>';foreach(['Shopee','Lazada','TikTok'] as $p)echo '<th>'.platform_label($p).'</th>';echo '<th>Validation</th></tr></thead><tbody>';foreach($rows as $id=>$x){$line=$plan[$id];$pcts=array_values(allocation_percentages($id));$rulesValid=count($pcts)===3&&min($pcts)>=0&&abs(array_sum($pcts)-100)<0.0000001;$rules=$rulesValid?array_values(allocate_integer($x['qty'],$pcts)):[0,0,0];echo '<tr data-incoming-row data-qty="'.$x['qty'].'" data-damaged="'.($x['damaged']?'1':'0').'" data-rules-valid="'.($rulesValid?'1':'0').'" data-rules="'.e(json_encode([$rules[1],$rules[0],$rules[2]])).'"><td>'.e($x['name']).($x['damaged']?'<small class="ia-damaged">Damaged / Leak → Non-Sellable</small>':'').'</td><td><b>'.$x['qty'].'</b></td>';foreach(['Shopee','Lazada','TikTok'] as $p)echo '<td>'.($editing?'<input aria-label="'.e($p.' quantity for '.$x['name']).'" type="number" min="0" max="'.$x['qty'].'" step="1" name="allocation['.$id.']['.$p.']" value="'.$line[$p].'" data-platform="'.$p.'" required '.($x['damaged']?'readonly':'').'>':'<b>'.$line[$p].'</b>').'</td>';echo '<td><span class="ia-badge" data-validation>'.($x['damaged']?'Non-Sellable':($line['Warehouse']?'Allocate '.$line['Warehouse'].' more':'✓ Fully Allocated')).'</span></td></tr>';}echo '</tbody><tfoot><tr><td>TOTAL</td>';foreach(['incoming','Shopee','Lazada','TikTok'] as $k)echo '<td data-total="'.$k.'">'.array_sum(array_column($plan,$k)).'</td>';echo '<td></td></tr></tfoot></table></div>';}
function incoming_history($b){$r=json_decode($b['result_json']??'[]',true)?:[];$a=$r['incoming_allocation']??null;if(!$a)return;$legacyWarehouse=array_sum(array_column($a['lines'],'Warehouse'))!==0;echo '<div class="card"><h3>Incoming Stock Allocation</h3><p class="muted">'.e($b['status']==='Confirmed'?'Posted allocation':'Saved review — no inventory posted').'. Reviewed by '.e($a['saved_name']??'').' · '.e($a['saved_at']??'').'</p><div class="table-wrap"><table class="table"><tr><th>Product</th><th>Incoming</th><th>Shopee</th><th>Lazada</th><th>TikTok</th>'.($legacyWarehouse?'<th>Legacy Warehouse</th>':'').'<th>Non-Sellable</th></tr>';foreach($a['lines'] as $x){echo '<tr><td>'.e($x['product']).'</td>';foreach(array_merge(['incoming','Shopee','Lazada','TikTok'],$legacyWarehouse?['Warehouse']:[],['Non-Sellable']) as $k)echo '<td>'.(int)$x[$k].'</td>';echo '</tr>';}echo '</table></div></div>';}
function incoming_allocation_page($id){$q=db()->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([$id]);$b=$q->fetch();if(!$b){echo '<div class="alert danger">Inflow not found.</div>';return;}usability_journey($b['status'],'Received products increase sellable or Non-Sellable stock according to their condition; allocation assigns sellable units to platforms.','?page=inflow&history=all');if($b['status']==='Cancelled'){echo inflow_cancelled_message($b);incoming_history($b);return;}if($b['status']==='Confirmed'){echo '<div class="alert info">This inflow is already confirmed.</div>';incoming_history($b);return;}try{$rows=incoming_rows($b);}catch(Throwable $e){if(can_action('cancel_inflow_upload'))echo inflow_cancel_form($id);echo '<div class="alert warn">'.e($e->getMessage()).'</div><a class="btn ghost" href="?page='.($b['batch_type']==='Receipt PDF'?'receipt_review':'inflow_batch').'&id='.$id.'">Back to Review</a>';return;}$r=json_decode($b['result_json']??'[]',true)?:[];$a=$r['incoming_allocation']??[];$signature=incoming_signature($b,$rows);$valid=isset($a['signature'])&&hash_equals($signature,$a['signature']);$input=$valid?$a['lines']:[];if($valid){try{incoming_plan($rows,$input);}catch(Throwable $e){$valid=false;}}if(!$a&&!$valid&&$b['batch_type']==='Manual'&&($r['condition']??'')==='Good Item'&&in_array($r['return_platform'],['Shopee','Lazada','TikTok'],true))$input[$r['product_id']][$r['return_platform']]=$r['qty'];$plan=incoming_plan($rows,$input,false);$final=($_GET['step']??'')==='confirm'&&$valid;$can=incoming_permission($b);$back='?page='.($b['batch_type']==='Receipt PDF'?'receipt_review':'inflow_batch').'&id='.$id;
 echo '<div class="ia-page"><div class="page-head"><div><h1>'.($final?'Inflow Final Confirmation':'Inflow Review &amp; Allocation').'</h1><p>Review incoming products and assign quantities before final confirmation.</p></div></div><div class="ia-steps"><div class="done"><span>✓</span>1. Review Items</div><div class="'.($final?'done':'active').'"><span>'.($final?'✓':'2').'</span>2. Platform Allocation</div><div class="'.($final?'active':'').'"><span>3</span>3. Final Confirmation</div></div><div class="ia-info">ⓘ &nbsp; No inventory has been added yet. Stocks and allocations update only after Confirm Inflow.</div>';
 if($a&&!$valid)echo '<div class="alert warn">Incoming details or allocation requirements changed. Review and submit a full allocation.</div>';
 echo '<form method="post" action="actions.php" id="incomingAllocationForm" '.($final?'data-confirm="Confirm this inflow and its displayed allocation? This will add inventory."':'').'><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="return" value="inflow_allocation&id='.$id.($final?'&step=confirm':'').'"><input type="hidden" name="signature" value="'.$signature.'"><input type="hidden" name="revision" value="'.(int)($a['revision']??0).'"><input type="hidden" name="allocation_revision" value="'.(int)($a['revision']??0).'"><input type="hidden" name="action" value="'.($final?($b['batch_type']==='Receipt PDF'?'confirm_receipt':($b['batch_type']==='Manual'?'confirm_manual_inflow':'confirm_bulk_inflow')):'save_inflow_allocation').'">';
 echo '<div class="ia-card"><div class="ia-card-head"><div><h2>'.($final?'Confirm Incoming Stock':'Allocate Incoming Stock').'</h2><p>'.($final?e($b['reference_no']).' · '.e($b['txn_date']):'Assign the full incoming quantity of each good item to platforms.').'</p></div>'.(!$final&&$can?'<button type="button" class="btn ghost" id="applyIncomingRules">☷ &nbsp; Apply Allocation Rules</button><button type="button" class="btn ghost" onclick="document.getElementById(\'incomingRuleDialog\').showModal()">Manage Default Rule</button>':'').'</div>';incoming_table($rows,$plan,!$final&&$can);echo '<div class="ia-note">Platform quantities must equal the full incoming quantity for every good item. Damaged / Leak items go to Non-Sellable and are excluded from platform allocation.</div><div class="ia-summary">';foreach(['incoming'=>'Incoming Stock','Shopee'=>'Shopee','Lazada'=>'Lazada','TikTok'=>'TikTok'] as $k=>$label)echo '<div><span class="ia-summary-icon">'.(in_array($k,['Shopee','Lazada','TikTok'],true)?platform_label($k):($k==='Warehouse'?'<svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 21V8l9-5 9 5v13M7 21V11h10v10M10 21v-5h4v5"/></svg>':ui_icon('Active Products'))).'</span><div><span>'.e($label).'</span><strong><b data-summary="'.$k.'">'.array_sum(array_column($plan,$k)).'</b> pcs</strong></div></div>';echo '</div><div class="ia-valid" id="incomingValidation" role="status">'.(array_sum(array_column($plan,'Warehouse'))?'Assign all incoming units before submitting.':'✓ &nbsp; All good items are fully allocated.').'</div>';if($final)echo '<label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed all incoming items, conditions and platform quantities. Confirm this transaction.</label>';echo '</div><div class="ia-bottom"><a class="btn ghost" href="'.($final?'?page=inflow_allocation&id='.$id:$back).'">'.($final?'Back to Allocation':'Back to Review').'</a><div class="ia-submit">'.($can?'<button class="btn primary" id="incomingSubmit" '.(array_sum(array_column($plan,'Warehouse'))?'disabled aria-disabled="true"':'').'>'.($final?'Confirm Inflow':'Submit for Final Confirmation').' &nbsp; ›</button>':'<span class="muted">You have view-only access.</span>').'<small>Preview and confirm before stock is posted.</small></div></div></form>';if(can_action('cancel_inflow_upload'))echo '<div class="ia-cancel">'.inflow_cancel_form($id).'</div>';echo '</div><script src="assets/inflow_allocation.js"></script>';if(!$final&&$can){echo '<dialog id="incomingRuleDialog" aria-labelledby="incomingRuleTitle"><div class="modal-card"><div class="modal-head"><h3 id="incomingRuleTitle">Allocation Rule Settings</h3><button type="button" onclick="this.closest(\'dialog\').close()" aria-label="Close allocation rules">×</button></div>';outflow_global_rule('', 'inflow_allocation&id='.$id);echo '<div class="modal-actions"><button type="button" class="btn ghost" onclick="this.closest(\'dialog\').close()">Close</button></div></div></dialog>';}
}
